      {
        items{
          id
          name
          column_values(ids: $columnIds){
            id
            type
            value
            text
            ... on ButtonValue{
              label
            }
            ... on StatusValue{
              label
            }
            ... on VoteValue{
              vote_count
            }
            ... on TagsValue{
              tags{
                  name
              }
          }
          ... on BoardRelationValue {
            linked_item_ids
          }
          ... on DependencyValue {
            linked_item_ids
          }
          ... on WeekValue {
            start_date
            end_date
          }
          }
        }
      }
    }
  }"];
