const js=v=>{if(!has(v))return undefined;try{return JSON.parse(v)}catch(e){return v}};
const send=(query,variables)=>{request.body={query,variables};return request};
return send(Q[0],{boardId:inputs.board_id,columnIds:js(inputs.column_ids)});

